def short_label(name):
    if name.lower()=='none':return 'Unbound'
    if name.startswith('Scancode') and name[8:].isdigit():return LABELS.get(int(name[8:]),name)
    if name in SHORT:return SHORT[name]
    if name.startswith('Keypad '):return 'Num'+name[7:].replace(' ','')
    return name

def palette_label(token):
    value=LABELS[token]
    return ('arrow',value.lower()) if value in ('Up','Down','Left','Right') else value

